import archetypesJson from "./data/archetypes.json" with { type: "json" };

import type { CatalogArchetype } from "./types.js";

/**
 * The shipped, window-scoped Limitless aliases.
 *
 * This table is small enough to sit in the core so `suggestArchetype` works
 * without importing the full card list. The card catalog stays on the
 * `@dierkens.dev/ptcg-decklist-tools/data` subpath. Generated by
 * `pnpm run archetypes`.
 */
export const archetypes: readonly CatalogArchetype[] =
  archetypesJson as readonly CatalogArchetype[];
